def normalize_legacy_task_statuses(apps, schema_editor):
    """Map legacy pipeline statuses (DRAFTING/WAITING/COMPLETED) to modern Kanban statuses."""
    TaskDocument = apps.get_model('workspace', 'TaskDocument')
    TaskDocument.objects.filter(status='DRAFTING').update(status='TODO')
    TaskDocument.objects.filter(status='WAITING').update(status='DOING')
    TaskDocument.objects.filter(status='COMPLETED').update(status='DONE')


